using namespace std;

class Solution {
public:
    int maxDepthBST(vector<int>& order) {
        map<int, int> depth;
        int maxD = 0;

        for (int x : order) {
            auto it = depth.lower_bound(x);
            int succD = (it != depth.end()) ? it->second : 0;
            int predD = (it != depth.begin()) ? prev(it)->second : 0;
            int d = 1 + max(predD, succD);
            depth[x] = d;
            maxD = max(maxD, d);
        }
        return maxD;
    }
};

import java.util.*;

class Solution {
    public int maxDepthBST(int[] order) {
        TreeMap<Integer, Integer> depth = new TreeMap<>();
        int maxD = 0;

        for (int x : order) {
            Integer lower = depth.lowerKey(x);
            Integer higher = depth.higherKey(x);
            int predD = lower != null ? depth.get(lower) : 0;
            int succD = higher != null ? depth.get(higher) : 0;
            int d = 1 + Math.max(predD, succD);
            depth.put(x, d);
            maxD = Math.max(maxD, d);
        }
        return maxD;
    }
}

/**
 * @param {number[]} order
