var maxDepthBST = function(order) {
    const inserted = [];
    const depth = new Map();
    let maxD = 0;

    for (let i = 0; i < order.length; ++i) {
        const x = order[i];
        let l = 0, r = inserted.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (inserted[mid] < x) l = mid + 1;
            else r = mid;
        }

        const predD = l > 0 ? depth.get(inserted[l - 1]) : 0;
        const succD = l < inserted.length ? depth.get(inserted[l]) : 0;
        const d = 1 + Math.max(predD, succD);
        depth.set(x, d);
        if (d > maxD) maxD = d;
        inserted.splice(l, 0, x);
    }
    return maxD;
};
